int path_to_string(struct super_block *sb, unsigned char *from, int fromlen, unsigned char *to, int tolen) {
    int ret = 0;
    int pos = 0;
    int i = 0;

    while (i < fromlen) {
        unsigned char type = from[i];
        int len = from[i + 1];

        if (len < 0 || i + len > fromlen) {
            return -EIO;
        }

        i += 2;

        if (type == DT_DIR) {
            if (pos + 1 >= tolen) {
                return -ENAMETOOLONG;
            }
            to[pos] = '/';
            pos++;
        } else if (type == DT_LNK) {
            if (pos + len >= tolen) {
                return -ENAMETOOLONG;
            }
            for (int j = 0; j < len; j++) {
                to[pos] = from[i];
                pos++;
                i++;
            }
        } else {
            if (pos + len + 1 >= tolen) {
                return -ENAMETOOLONG;
            }
            for (int j = 0; j < len; j++) {
                to[pos] = from[i];
                pos++;
                i++;
            }
            to[pos] = '\0';
            pos++;
        }
    }

    if (pos >= tolen) {
        return -ENAMETOOLONG;
    }

    to[pos] = '\0';
    return ret;
}

int path_to_char_string(struct super_block *sb, unsigned char *from, int fromlen, unsigned char *to, int tolen) {
    int i = 0, j = 0;
    unsigned char *end = to + tolen;

    while (i < fromlen) {
        int len = from[i];

        if (len == 0) {
            // End of path components
            break;
        }

        if (len > fromlen - i - 1) {
            // Invalid component length
            return -EIO;
        }

        if (j + len + 1 > tolen) {
            // Output buffer overflow
            return -ENAMETOOLONG;
        }

        // Copy the component to the output buffer
        memcpy(to + j, from + i + 1, len);
        j += len;
        to[j++] = '/'; // Add separator

        i += len + 1;
    }

    if (j > 0) {
        to[j - 1] = '\0'; // Null-terminate the string and remove trailing slash
    } else {
        to[0] = '\0';
    }

    return 0;
}

