int name_to_char_string(struct super_block *sb, unsigned char *from, int fromlen, unsigned char *to, int tolen) {
    int i = 0, j = 0;

    if (tolen <= 0)
        return -EINVAL;

    if (fromlen <= 0)
        return -EINVAL;

    if (from == NULL || to == NULL)
        return -EFAULT;

    while (i < fromlen && j < tolen - 1) {
        if (from[i] == 0) {
            to[j++] = '/';
        } else if (from[i] == 1) {
            int name_len = from[i + 1];
            if (j + name_len >= tolen) {
                return -ENAMETOOLONG;
            }
            memcpy(&to[j], &from[i + 2], name_len);
            j += name_len;
            i += name_len + 2;
        } else {
            return -EIO;
        }

        i++;
    }

    if (j >= tolen) {
        return -ENAMETOOLONG;
    }

    to[j] = '\0';
    return 0;
}

int path_to_string(struct super_block *sb, unsigned char *from, int fromlen, unsigned char *to, int tolen) {
    int pos = 0;
    int i = 0;

    while (i < fromlen) {
        if (pos >= tolen - 1) {
            return -ENAMETOOLONG;
        }

        if (from[i] == '/') {
            to[pos++] = '/';
            i += 2;
        } else if (from[i] == '.') {
            to[pos++] = '.';
            if (i + 2 <= fromlen && from[i + 1] == '/') {
                i += 2;
            } else {
                i++;
            }
        } else {
            while (i < fromlen && from[i] != '/' && from[i] != '.') {
                if (pos >= tolen - 1) {
                    return -ENAMETOOLONG;
                }
                to[pos++] = from[i++];
            }
        }
    }

    if (pos < tolen) {
        to[pos] = '\0';
    } else {
        return -ENAMETOOLONG;
    }

    return 0;
}

int path_to_char(struct super_block *sb, unsigned char *from, int fromlen, unsigned char *to, int tolen) {
    int i = 0, j = 0;

    if (tolen <= 0)
        return -EINVAL;

    while (i < fromlen && j < tolen - 1) {
        if (from[i] == '/') {
            if (j < tolen - 1)
                to[j++] = '/';
            i++;
        } else if (from[i] == '.' && (i + 1 == fromlen || from[i + 1] == '/')) {
            if (j == 0 || (j > 0 && to[j - 1] != '/')) {
                if (j < tolen - 1)
                    to[j++] = '.';
                if (j < tolen - 1)
                    to[j++] = '/';
            }
            i++;
        } else {
            if (from[i] != '\0') {
                if (j < tolen - 1)
                    to[j++] = from[i];
                i++;
            } else {
                break;
            }
        }
    }

    if (i < fromlen)
        return -ENAMETOOLONG;

    if (j < tolen)
        to[j] = '\0';
    else
        return -ENAMETOOLONG;

    return 0;
}
